import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, sin, texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;
  const root = new Group();
  const resources = [];
  const timelines = [];
  const primitiveCleanups = [];
  let cleaned = false;

  root.userData.handlers = {};

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const surface = new MeshBasicNodeMaterial({
    transparent: false,
    toneMapped: false
  });

  const coordinates = uv();
  const vertical = smoothstep(0.0, 1.0, coordinates.y);
  const baseGradient = mix(
    vec3(0.043, 0.043, 0.063),
    vec3(0.086, 0.086, 0.114),
    vertical
  );
  const grain = sin(
    coordinates.x.mul(241.0).add(coordinates.y.mul(173.0))
  ).mul(0.006);

  surface.colorNode = baseGradient.add(vec3(grain));
  surface.roughness = 0.72;
  resources.push(surface);

  const cardGeometry = new PlaneGeometry(4.8, 3.0);
  const card = new Mesh(cardGeometry, surface);
  card.position.z = -0.02;
  root.add(card);
  resources.push(cardGeometry);

  const accentMaterial = new MeshBasicNodeMaterial({
    color: colors.accent,
    toneMapped: false
  });
  const accentGeometry = new PlaneGeometry(0.9, 0.025);
  const accent = new Mesh(accentGeometry, accentMaterial);
  accent.position.set(-1.72, 0.62, 0.035);
  root.add(accent);
  resources.push(accentGeometry, accentMaterial);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const label = ctx.fontAtlas.createText(String(item.text ?? ''), {
      fontSize: item.typography?.fontSize ?? 39,
      color: colors.paper,
      align: 'left'
    });
    label.position.set(-1.72, -0.32, 0.045);
    root.add(label);
  }

  const imageGeometry = new PlaneGeometry(1.05, 1.05);
  const imageMaterial = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0.92,
    toneMapped: false
  });
  const imagePlane = new Mesh(imageGeometry, imageMaterial);
  imagePlane.position.set(1.25, 0.2, 0.04);
  root.add(imagePlane);
  resources.push(imageGeometry, imageMaterial);

  const imageUrl = config.imageUrl;
  let loadedTexture = null;

  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      if (cleaned) {
        tex.dispose?.();
        return;
      }

      loadedTexture = tex;
      if (ctx.THREE.SRGBColorSpace) tex.colorSpace = ctx.THREE.SRGBColorSpace;
      imageMaterial.colorNode = texture(tex);
      imageMaterial.needsUpdate = true;
    });
  }

  for (const primitive of config.cinematicPrimitives ?? []) {
    const result = ctx.primitives[primitive.name]?.(root, primitive.params);
    if (result?.cleanup) primitiveCleanups.push(result.cleanup);
    if (result?.timeline) timelines.push(result.timeline);
  }

  const entrance = gsap.timeline();
  entrance.fromTo(
    root.scale,
    { x: 0.965, y: 0.965, z: 0.965 },
    {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.7,
      ease: 'power3.out'
    }
  );
  timelines.push(entrance);

  root.userData.cleanup = () => {
    if (cleaned) return;
    cleaned = true;

    for (const timeline of timelines) {
      timeline?.kill?.();
    }

    for (const cleanup of primitiveCleanups) {
      cleanup?.();
    }

    if (loadedTexture) loadedTexture.dispose?.();

    for (const resource of resources) {
      resource?.dispose?.();
    }
  };

  return root;
}
